function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function Svg({svg}:{svg:string}){return <div className="svg-frame" dangerouslySetInnerHTML={{__html:svg}}/>;}
function Numeric({label,value,onChange,q='length',units,min=0,help,readOnly=false}:{label:string;value:number;onChange:(n:number)=>void;q?:Quantity;units:'US'|'SI';min?:number;help?:string;readOnly?:boolean}){
 const display=toDisplay(value,q,units);const [text,setText]=useState(Number.isFinite(display)?String(Number(display.toPrecision(8))):'');
 useEffect(()=>setText(Number.isFinite(display)?String(Number(display.toPrecision(8))):''),[display,units]);
 return <label className="field"><span>{label}{help&&<span className="help-tip" title={help}><CircleHelp size={12}/></span>}</span><div className={`number-wrap ${!Number.isFinite(value)||value<min?'invalid':''}`}><input aria-label={label} type="number" step="any" readOnly={readOnly} min={toDisplay(min,q,units)} value={text} onChange={e=>{setText(e.target.value);onChange(e.target.value===''?NaN:fromDisplay(Number(e.target.value),q,units));}}/><span>{unit(q,units)}</span></div></label>;
}
function TextField({label,value,onChange,placeholder}:{label:string;value:string;onChange:(s:string)=>void;placeholder?:string}){return <label className="field"><span>{label}</span><input value={value} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></label>;}
const worksheetSections = ['Geometry','Crane loads','Criteria','Connections','Existing building','Validation','Project'];
